-- =====================================================================
-- AZ/seed_students_300.sql
--
-- 300 synthetic students for system testing.  The CURRENT public.students
-- shape is honoured exactly: 036 dropped verification_status,
-- mismatch_count, reviewed_at, must_change_password and session_version,
-- so none of those columns appear below.
--
-- WHAT LANDS
--   lrn            999900000001 .. 999900000300   (12 digits, unique)
--   email          sample.student001 .. sample.student300 @cnnhs.edu
--   grade_level    Grade 7 .. Grade 12, 50 each
--   gender         Male / Female alternating, 150 each
--   birthdate      age = grade + 5, so Grade 7 ~ 2014 ... Grade 12 ~ 2009
--   status         'approved' -- verify_student_credentials_rpc only finds
--                  approved students (031:180), so this is what makes them
--                  usable in the voting / past-election flow.
--   password_hash  the SHA-256 hex of 'student123' (see TEST LOGIN)
--   id, student_id, masterlist_id, reviewed_by, registered_at: left to the
--                  table defaults / NULL.
--
-- TEST LOGIN
--   Every one of the 300 shares the password:   student123
--   password_hash is stored as the legacy 64-hex SHA-256 (NOT bcrypt),
--   which both verifiers accept:
--     * web  : login_student_direct_v2 takes the D-10 "anything else"
--              branch, compares sha256(password) (023:276) and
--              transparently re-hashes to bcrypt on first login.
--     * kiosk: verify_student_credentials_rpc receives the same SHA-256 hex
--              from the client, so its equality branch matches (031:197).
--   Same password for both, no re-seeding needed after the first login
--   rewrites the row to bcrypt.
--
-- IDEMPOTENT
--   "on conflict do nothing" skips any row whose lrn/email already exists
--   instead of aborting, so this file is safe to re-run.  The verify query
--   at the end reports the true counts.
--
-- NOT DELETE-FRIENDLY, BY DESIGN
--   052's students_no_delete_with_history trigger refuses to delete a
--   student who has a candidacy or a vote.  Once these students are used
--   in the past-election test they are permanent; to start over, clear
--   votes/candidates (AZ/reset_election_data.sql) first.
--
-- RUN AS: the SQL editor's owner role.  RLS is enabled on students but not
--   FORCED, so the "students public registration insert" policy is not what
--   lets this through -- the owner bypasses RLS.
-- =====================================================================

begin;

on conflict do nothing;

commit;

-- ---------------------------------------------------------------------
-- Verify: seeded should reach 300 (300 synthetic_total), 300 distinct lrn
-- and 300 distinct email.  If seeded < 300 but synthetic_total = 300, those
-- rows already existed and nothing was lost.
-- ---------------------------------------------------------------------
select
  count(*)                                                       as students_total,
  count(*) filter (where lrn like '9999%')                       as synthetic_total,
  count(distinct lrn) filter (where lrn like '9999%')            as distinct_lrn,
  count(distinct email) filter (where lrn like '9999%')          as distinct_email;